(* [comment removed for export] *)
Lemma elemsW_Forall_off : forall b es A n,
  mb_addr_ok b es -> (forall x s, In (x, s) es -> A + n <= x \/ x + mb_block_size s <= A) ->
  Forall (fun iv : Z * Z => A + n <= fst iv \/ snd iv <= A) (mb_elemsW es).
Proof.
  intros b es A n AOK SEP. apply Forall_forall. intros [l h] IN.
  assert (K : exists x s, In (x, s) es /\ l = x /\ h = x + 24 + s).
  { clear - IN. induction es as [|[x s] es IH]; cbn in IN; [destruct IN|].
    destruct IN as [E|IN]; [injection E as <- <-; exists x, s; split; [left; reflexivity| split; reflexivity]|].
    destruct (IH IN) as (x' & s' & IN' & E1 & E2). exists x', s'. split; [right; exact IN'| split; assumption]. }
  destruct K as (x & s & INe & -> & ->). cbn [fst snd].
  destruct (mb_addr_ok_elem _ _ _ _ AOK INe) as (_ & _ & S0 & S24 & _). destruct (SEP x s INe); lia.
Qed.

(* [comment removed for export] *)
Lemma elemsW_Forall_hi : forall b es A k, mb_addr_ok b es -> aceil <= A -> Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) (mb_elemsW es).
Proof.
  intros b es A k AOK HA. apply Forall_forall. intros [l h] IN.
  assert (K : exists x s, In (x, s) es /\ l = x /\ h = x + 24 + s).
  { clear - IN. induction es as [|[x s] es IH]; cbn in IN; [destruct IN|].
    destruct IN as [E|IN]; [injection E as <- <-; exists x, s; split; [left; reflexivity| split; reflexivity]|].
    destruct (IH IN) as (x' & s' & IN' & E1 & E2). exists x', s'. split; [right; exact IN'| split; assumption]. }
  destruct K as (x & s & INe & -> & ->). cbn [fst snd].
  destruct (mb_addr_ok_elem _ _ _ _ AOK INe) as (_ & _ & S0 & S24 & _ & _ & XCE & _). right. lia.
Qed.

Lemma elemsW_noshadow : forall b es, mb_addr_ok b es -> Forall noshadow (mb_elemsW es).
Proof.
  intros b es AOK. apply Forall_forall. intros [l h] IN.
  assert (K : exists x s, In (x, s) es /\ l = x /\ h = x + 24 + s).
  { clear - IN. induction es as [|[x s] es IH]; cbn in IN; [destruct IN|].
    destruct IN as [E|IN]; [injection E as <- <-; exists x, s; split; [left; reflexivity| split; reflexivity]|].
    destruct (IH IN) as (x' & s' & IN' & E1 & E2). exists x', s'. split; [right; exact IN'| split; assumption]. }
  destruct K as (x & s & INe & -> & ->). unfold noshadow. cbn [fst snd].
  destruct (mb_addr_ok_elem _ _ _ _ AOK INe) as (_ & _ & S0 & S24 & _ & _ & _ & _ & AP & _). pose proof (aapp_not_shadowland _ _ AP). lia.
Qed.
